import{_ as t,o,c as l,a2 as n}from"./chunks/framework.BV21bweQ.js";const q=JSON.parse('{"title":"太空巨构","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/太空巨构.md","filePath":"中层/世界/太空巨构.md","lastUpdated":1787066340000}'),i={name:"中层/世界/太空巨构.md"};function s(a,r,g,e,h,u){return o(),l("div",null,[...r[0]||(r[0]=[n('<h1 id="太空巨构" tabindex="-1">太空巨构 <a class="header-anchor" href="#太空巨构" aria-label="Permalink to &quot;太空巨构&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文档描述世界观中的太空巨型构造物，这些是神机在间章时期建造的宇宙级工程，主要用于监控、防御和管理银河系。这些巨构体现了神机计划的宏大尺度和技术实力，但大多数福瑞种族不了解这些设施的存在和真正目的。</p><h2 id="主要太空巨构" tabindex="-1">主要太空巨构 <a class="header-anchor" href="#主要太空巨构" aria-label="Permalink to &quot;主要太空巨构&quot;">​</a></h2><h3 id="银河之眼" tabindex="-1">银河之眼 <a class="header-anchor" href="#银河之眼" aria-label="Permalink to &quot;银河之眼&quot;">​</a></h3><h4 id="基本描述" tabindex="-1">基本描述 <a class="header-anchor" href="#基本描述" aria-label="Permalink to &quot;基本描述&quot;">​</a></h4><ul><li><strong>位置</strong>：银河中心超大黑洞处</li><li><strong>类型</strong>：超级监控机器</li><li><strong>建造者</strong>：神机</li><li><strong>建造时间</strong>：间章时期</li><li><strong>当前状态</strong>：运行中，作为世界树的替代监控方案</li></ul><h4 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h4><p><strong>监控能力：</strong></p><ul><li><strong>夸克级监控</strong>：能够做到对银河系的夸克级监控，精确到微观粒子层面</li><li><strong>全景监控</strong>：监控整个银河系的动态，包括太阳系内外的所有变化</li></ul><p><strong>控制能力：</strong></p><ul><li><strong>反向控制</strong>：甚至可以反向控制（如时间暂停），具有强大的干预能力</li><li><strong>悖论科技</strong>：其部件包含悖论科技，需要神机本人在场用神权驱动</li><li><strong>谨慎使用</strong>：神机几乎不用它，因为一旦它进入故事，就可能被摧毁，导致银河系完蛋</li></ul><h4 id="战略意义" tabindex="-1">战略意义 <a class="header-anchor" href="#战略意义" aria-label="Permalink to &quot;战略意义&quot;">​</a></h4><p><strong>替代监控角色：</strong></p><ul><li><strong>主监控设施</strong>：在世界树被毁后成为主要的监控设施</li><li><strong>安全保障</strong>：不轻易使用以避免进入叙事和风险</li><li><strong>备用方案</strong>：作为关键情况下的备用监控和控制手段</li></ul><p><strong>使用限制与风险：</strong></p><ul><li><strong>叙事风险</strong>：一旦进入叙事就可能被摧毁，导致严重后果</li><li><strong>操作要求</strong>：需要神机本人在场用神权驱动</li></ul><h3 id="克隆仓库" tabindex="-1">克隆仓库 <a class="header-anchor" href="#克隆仓库" aria-label="Permalink to &quot;克隆仓库&quot;">​</a></h3><h4 id="基本描述-1" tabindex="-1">基本描述 <a class="header-anchor" href="#基本描述-1" aria-label="Permalink to &quot;基本描述&quot;">​</a></h4><ul><li><strong>位置</strong>：太空/近地轨道</li><li><strong>类型</strong>：克隆体储存设施</li><li><strong>建造者</strong>：神机</li><li><strong>建造时间</strong>：间章时期</li><li><strong>当前状态</strong>：仍在太空运转</li></ul><h4 id="功能与目的" tabindex="-1">功能与目的 <a class="header-anchor" href="#功能与目的" aria-label="Permalink to &quot;功能与目的&quot;">​</a></h4><p><strong>核心功能：</strong></p><ul><li><strong>克隆体储存</strong>：克隆无数个与毁灭神本体完全一致的克隆体</li><li><strong>意识连接</strong>：通过意识连接技术让克隆体成为毁灭神&quot;意识整体&quot;的一部分</li><li><strong>神权稀释</strong>：稀释毁灭神权，使其危险性降低到可控范围</li><li><strong>风险控制</strong>：作为控制毁灭神权的手段之一，防止毁灭神权过度集中</li></ul><p><strong>技术机制详解：</strong></p><ol><li><p><strong>意识连接网络：</strong></p><ul><li><strong>整体意识</strong>：建立克隆体与毁灭神本体的意识连接</li><li><strong>网络同步</strong>：所有克隆体共享部分意识，形成意识整体</li><li><strong>神权锚定</strong>：毁灭神的神权锚定其&quot;意识整体&quot;（本体 + 所有克隆体）</li></ul></li><li><p><strong>神权稀释原理：</strong></p><ul><li><strong>总量恒定</strong>：神权总量恒定，不会增加或减少</li><li><strong>分散锚定</strong>：通过大量克隆体分散和稀释毁灭神权</li><li><strong>力量削弱</strong>：神权被无数克隆体稀释后力量薄弱到无法感知自身神权</li></ul></li><li><p><strong>记忆修改技术：</strong></p><ul><li><strong>物理层面失忆</strong>：对毁灭神实施生理层面的大脑记忆修改</li><li><strong>成为普通少年</strong>：使其失忆，成为一位普通少年</li><li><strong>安全性提升</strong>：降低毁灭神权的危险性和不可控性</li></ul></li></ol><h4 id="战略意义-1" tabindex="-1">战略意义 <a class="header-anchor" href="#战略意义-1" aria-label="Permalink to &quot;战略意义&quot;">​</a></h4><p><strong>神权控制体系：</strong></p><ul><li><strong>核心控制</strong>：控制毁灭神权的重要设施</li><li><strong>安全措施</strong>：防止毁灭神权过度集中的安全措施</li><li><strong>长期布局</strong>：体现神机长期战略布局的深度</li></ul><p><strong>风险与伏笔：</strong></p><ul><li><strong>回流风险</strong>：克隆仓库若被损毁/克隆体批量死亡，被稀释的神权则会回流至本体</li><li><strong>失控可能</strong>：可能引发主角失控/恢复神权，形成故事转折点</li></ul><h3 id="月球武器平台" tabindex="-1">月球武器平台 <a class="header-anchor" href="#月球武器平台" aria-label="Permalink to &quot;月球武器平台&quot;">​</a></h3><h4 id="基本描述-2" tabindex="-1">基本描述 <a class="header-anchor" href="#基本描述-2" aria-label="Permalink to &quot;基本描述&quot;">​</a></h4><ul><li><strong>位置</strong>：月球，地月系内</li><li><strong>类型</strong>：对基底层特化武器平台</li><li><strong>建造者</strong>：神机</li><li><strong>建造时间</strong>：间章时期</li><li><strong>当前状态</strong>：运行中，随时待命</li></ul><h4 id="改造规模与结构" tabindex="-1">改造规模与结构 <a class="header-anchor" href="#改造规模与结构" aria-label="Permalink to &quot;改造规模与结构&quot;">​</a></h4><p><strong>全面改造：</strong></p><ul><li><strong>天体改造</strong>：如今太阳系内绝大多数天体都已被神机改造过</li><li><strong>月球改造</strong>：月球是改造幅度最大的天体之一</li><li><strong>内部重构</strong>：月球内部几乎已无自然的地壳结构，而是充满了高强度材料构成的支撑结构与武器系统</li></ul><h4 id="功能定位" tabindex="-1">功能定位 <a class="header-anchor" href="#功能定位" aria-label="Permalink to &quot;功能定位&quot;">​</a></h4><p><strong>主要定位：</strong></p><ul><li><strong>对基底层特化</strong>：专门针对基底层现象和威胁设计</li><li><strong>地球防御</strong>：主要功能是对地球进行压制和防御</li><li><strong>空间修补</strong>：具备修补宇宙空间缝隙的能力</li></ul><p><strong>具体功能：</strong></p><p><strong>地球压制功能：</strong></p><ul><li><strong>炮口对准地球</strong>：炮口常对准地球，特别是已经炸裂、处于漂浮状态的<strong>北美洲</strong></li><li><strong>地脉监控</strong>：一旦地球的&quot;伤口&quot;（地脉）有失控风险，月球便会开火</li><li><strong>持续压制</strong>：用光束进行持续压制，防止地脉伤口恶化</li></ul><p><strong>空间修补功能：</strong></p><ul><li><strong>缝隙修补</strong>：用于修补宇宙中的空间缝隙，维护现实世界稳定性</li></ul><p><strong>超距打击技术：</strong></p><ul><li><strong>原理应用</strong>：光束融合了<strong>超距作用</strong>原理，可在宇宙范围内实现&quot;指哪打哪&quot;的超距打击</li><li><strong>无视距离</strong>：可实现&quot;指哪打哪&quot;的超距打击，无视距离限制</li><li><strong>防御突破</strong>：这种打击方式极难防御，具有战略威慑力</li></ul><h4 id="地球现状关联" tabindex="-1">地球现状关联 <a class="header-anchor" href="#地球现状关联" aria-label="Permalink to &quot;地球现状关联&quot;">​</a></h4><p><strong>北美洲状况：</strong></p><ul><li><strong>彻底炸裂</strong>：北美洲已在前传灾难中彻底炸裂</li><li><strong>漂浮状态</strong>：处于破碎漂浮状态，需要持续稳定</li><li><strong>压制重点</strong>：成为月球武器平台的重点压制区域</li></ul><p><strong>亚洲相对完整：</strong></p><ul><li><strong>故事发生地</strong>：故事主要发生的亚洲地区相对完整</li><li><strong>裂缝终止</strong>：地脉裂缝延伸至此便已终止，未造成全面破坏</li><li><strong>区域稳定</strong>：该区域相对稳定，适合福瑞种族生存发展</li></ul><h3 id="天穹-天幕" tabindex="-1">天穹（天幕） <a class="header-anchor" href="#天穹-天幕" aria-label="Permalink to &quot;天穹（天幕）&quot;">​</a></h3><h4 id="基本描述-3" tabindex="-1">基本描述 <a class="header-anchor" href="#基本描述-3" aria-label="Permalink to &quot;基本描述&quot;">​</a></h4><ul><li><strong>类型</strong>：人工天幕</li><li><strong>建造者</strong>：神机</li><li><strong>建造目的</strong>：掩饰神机改造太阳系的动作</li><li><strong>当前状态</strong>：已在天穹破碎事件中被撞碎，部分碎块坠落留存于大陆</li></ul><h4 id="结构特点" tabindex="-1">结构特点 <a class="header-anchor" href="#结构特点" aria-label="Permalink to &quot;结构特点&quot;">​</a></h4><ul><li><strong>六边形模块</strong>：天穹由巨大的六边形模块构成，六边形是神机所造人工天幕的原生几何结构</li><li><strong>尺寸巨大</strong>：单个六边形模块坠落后即可构成狮族所在的&quot;六边形沙漠&quot;</li></ul><blockquote><p>天穹在福瑞视角下的表象（天空破碎、六边形碎块等）<strong>详细内容参见</strong>：<a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></p></blockquote><h2 id="天穹破碎事件" tabindex="-1">天穹破碎事件 <a class="header-anchor" href="#天穹破碎事件" aria-label="Permalink to &quot;天穹破碎事件&quot;">​</a></h2><h3 id="事件概述" tabindex="-1">事件概述 <a class="header-anchor" href="#事件概述" aria-label="Permalink to &quot;事件概述&quot;">​</a></h3><ul><li><strong>发生时间</strong>：建国22年</li><li><strong>表象</strong>：天空破碎，掉下巨大的六边形碎块以及一个物体（实为坠毁的外星飞船）</li><li><strong>短暂出现</strong>：外星种族焰种短暂出现</li><li><strong>最终结果</strong>：灾难被神明解决，焰种再没有人见过</li></ul><h3 id="事件本质" tabindex="-1">事件本质 <a class="header-anchor" href="#事件本质" aria-label="Permalink to &quot;事件本质&quot;">​</a></h3><ul><li><strong>太阳系大战</strong>：并非单纯的天灾，而是<strong>神机与外星文明的太阳系大战</strong>（防守战）</li><li><strong>战争性质</strong>：是神机遭受的<strong>最大挫败之一</strong>，影响了后续的太空战略</li></ul><h3 id="战争过程" tabindex="-1">战争过程 <a class="header-anchor" href="#战争过程" aria-label="Permalink to &quot;战争过程&quot;">​</a></h3><ul><li><strong>入侵方向</strong>：外星文明入侵太阳系，从冥王星一路打到地球轨道</li><li><strong>创造神权应用</strong>：神机利用其创造神权（可先有结果再补过程，甚至紧急制造悖论）以诡异的速度进步和反击，将战线推回冥王星</li><li><strong>激烈对抗</strong>：战争范围横跨整个太阳系，形势一度极为危急</li><li><strong>唯一优势</strong>：前传BOSS遗留的<strong>特殊材料</strong>，凭借其超乎想象的强度，能够硬扛几发超距武器的攻击——当时地球科技对超距武器完全无法防御</li></ul><h3 id="结局与影响" tabindex="-1">结局与影响 <a class="header-anchor" href="#结局与影响" aria-label="Permalink to &quot;结局与影响&quot;">​</a></h3><ul><li><strong>成功击退</strong>：神机最终在<strong>地月系</strong>击退了外星入侵者，将其势力彻底赶出太阳系</li><li><strong>战略调整</strong>：此后，她向宇宙的探索变得<strong>更加谨慎</strong>，不再冒进</li></ul><h3 id="天穹破碎的真实由来" tabindex="-1">天穹破碎的真实由来 <a class="header-anchor" href="#天穹破碎的真实由来" aria-label="Permalink to &quot;天穹破碎的真实由来&quot;">​</a></h3><ul><li><strong>飞船坠毁</strong>：战斗中，一艘外星飞船坠毁，撞上了神机为掩饰自己改造太阳系动作而制造的<strong>天幕</strong></li><li><strong>事件形成</strong>：形成&quot;天穹破碎&quot;事件，被福瑞种族误解为天灾</li><li><strong>焰种</strong>：坠毁飞船上的外星种族——<strong>焰种</strong>（接触氧气即自燃，因死亡时燃烧被贬称为&quot;焰种&quot;）——短暂出现；残部逃窜伪装当地原住民企图生存延续，但太空战争结束后被神机的精灵部队搜查猎杀殆尽——因为不能让他们牵扯到故事里</li></ul><h2 id="天穹与狮族的关联" tabindex="-1">天穹与狮族的关联 <a class="header-anchor" href="#天穹与狮族的关联" aria-label="Permalink to &quot;天穹与狮族的关联&quot;">​</a></h2><h3 id="六边形沙漠的本质" tabindex="-1">六边形沙漠的本质 <a class="header-anchor" href="#六边形沙漠的本质" aria-label="Permalink to &quot;六边形沙漠的本质&quot;">​</a></h3><ul><li><strong>天穹碎块</strong>：狮族占据的六边形沙漠并非自然地貌，而是<strong>天穹破碎事件中掉落的天穹碎块</strong></li><li><strong>原生结构</strong>：六边形是神机所造人工天幕的原生几何结构，体现模块化设计</li></ul><h3 id="狮族的生存困境" tabindex="-1">狮族的生存困境 <a class="header-anchor" href="#狮族的生存困境" aria-label="Permalink to &quot;狮族的生存困境&quot;">​</a></h3><ul><li><strong>沙漠升温</strong>：六边形沙漠温度奇高，与周边环境差异显著，近百年持续升温成为无人区</li><li><strong>能量泄露</strong>：升温原因并非自然气候，而是天穹碎块的<strong>能量管线出现错误泄露</strong>，高能能量持续释放</li><li><strong>种族危机</strong>：狮族面临种族存续的燃眉之急，家园逐渐变为无法生存的环境</li></ul><h3 id="狮族的科技与战力来源" tabindex="-1">狮族的科技与战力来源 <a class="header-anchor" href="#狮族的科技与战力来源" aria-label="Permalink to &quot;狮族的科技与战力来源&quot;">​</a></h3><p><strong>橙黄色高能结晶：</strong></p><ul><li><strong>形成原因</strong>：天穹能量管线泄露的高能能量浸入附近岩石层，形成特殊的橙黄色高能结晶</li><li><strong>军事应用</strong>： <ul><li><strong>高能炸药</strong>：磨成粉末可作为极高能炸药</li><li><strong>高能燃料</strong>：整块作为极高能燃料</li></ul></li><li><strong>战力基础</strong>：是狮族的核心战力基础，赋予小族抗衡鹿熊等大族的实力</li></ul><p><strong>外星飞船残骸：</strong></p><ul><li><strong>残骸来源</strong>：天穹破碎时，撞在天幕上的<strong>外星宇宙飞船残骸</strong>留存于六边形沙漠</li><li><strong>科技影响</strong>： <ul><li><strong>审美塑造</strong>：让狮族的审美形成&quot;异域&quot;色彩</li><li><strong>技术飞跃</strong>：推动狮族科技树突飞猛进，获得异域科技</li></ul></li><li><strong>战力组合</strong>：高能结晶特性 + 外星科技，形成独特的战力体系</li></ul><p><strong>双刃剑效应：</strong></p><ul><li><strong>力量代价</strong>：狮族依赖的天穹碎块能量系统因泄露逐渐不稳定，是家园升温的直接原因</li><li><strong>饮鸩止渴</strong>：这份强大力量从一开始就是&quot;饮鸩止渴&quot;，在获得战力的同时面临生存危机</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./神机谋划">神机谋划</a></li><li><a href="./特殊地点">特殊地点</a></li><li><a href="./地脉与魔法">地脉与魔法</a></li><li><a href="./../历史/间章历史">间章历史</a></li><li><a href="./../人物/神机">神机</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li><li><a href="./龙族真相">龙族真相</a></li></ul><hr>',84)])])}const c=t(i,[["render",s]]);export{q as __pageData,c as default};
